import json
h,w=20,29
g=[[1]*w for _ in range(h)]
def frame(r0,c0,n,color,fill):
    for r in range(r0,r0+n):
        for c in range(c0,c0+n):
            if r in (r0,r0+n-1) or c in (c0,c0+n-1):
                g[r][c]=color
            else:
                g[r][c]=fill
frame(0,4,4,5,2)
frame(6,13,7,4,7)
frame(14,10,3,5,7)
assert len(g)==20 and all(len(row)==29 for row in g)
assert set(sum(g,[])) <= set(range(10))
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
